def 計算適合字型(文字內容, 區域寬度mm, 字型縮放=1.0):
    """根據文字內容和區域寬度計算適合的字型大小"""
    字元寬度係數 = 0.6
    估算文字寬度 = len(文字內容) * 字元寬度係數
    最大字型 = (區域寬度mm / 估算文字寬度) * 10 * 字型縮放 if 區域寬度mm > 0 else 8
    最小字型 = 6 * 字型縮放
    最大字型限制 = 14 * 字型縮放
    return max(最小字型, min(最大字型限制, 最大字型))


